import { useAccountCreateTokenList } from '@/hook/pump/useAccountCreateTokenList'
import useAccountCreateTokenListStore from '@/store/accountCreateTokenList'
import { PumpToken, PumpTokenDetail } from '@/type/pump'
import { Block } from '@cetus/design'
import { useJump2Dex } from '@cetus/hooks'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Pagination, Table } from '@cetus/ui-kit'
import H5MapTable from '@cetus/ui-kit/src/components/H5MapTable'
import { Decimal, formatCurrency, formatNumber, formatNumberWithKMB } from '@cetus/utils'
import { fromDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { Center, HStack, Text, VStack } from '@chakra-ui/react'
import { SUI_TYPE_ARG } from '@mysten/sui/utils'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import FetchError from '../common/FetchError'
import MarketCapBlock from '../common/MarketCapBlock'
import SingleHasAddress from './SingleHasAddress'
import TokensCreatedStatus from './TokensCreatedStatus'
const getColumns = (getTokenAmountValue: (coinType?: string, amount?: string) => string, isApp: boolean) => {
  return [
    {
      title: <Text fontSize="14px">Name (Symbol)</Text>,
      key: 'name',
      render: (item: PumpToken, index: number) => {
        return (
          <HStack
            align="center"
            w={{
              base: 'calc(100% - 120px)',
              lg: 'unset'
            }}
          >
            <SingleHasAddress
              pumpTokenInfo={item}
              w={{
                base: 'unset',
                lg: '190px'
              }}
            />
          </HStack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Contract</Text>,
      key: 'address',
      // 控制整列的显示逻辑 只在h5展示这一行
      hidden: !isApp,
      render: (item: PumpToken, index: number) => {
        return (
          <HStack
            w={{
              base: 'calc(100% - 120px)',
              lg: 'unset'
            }}
            align="center"
          >
            <SingleHasAddress
              isRowH5={true}
              pumpTokenInfo={item}
              w={{
                base: 'unset',
                lg: '190px'
              }}
            />
          </HStack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Status</Text>,
      key: 'status',
      render: ({ status }: { status: number }) => {
        return <TokensCreatedStatus status={status} />
      }
    },
    {
      title: <Text fontSize="14px">Price</Text>,
      key: 'price',
      render: ({ current_ui_price }: { current_ui_price: string }) => {
        return (
          <VStack
            align={{
              base: 'flex-end',
              lg: 'flex-start'
            }}
            gap="0"
          >
            <Text color="text_caption">
              {+current_ui_price ? `${formatNumber(current_ui_price, undefined, undefined, Decimal.ROUND_DOWN)} SUI` : '--'}{' '}
            </Text>
            <Text fontSize="12px"> {+current_ui_price ? formatCurrency(getTokenAmountValue(SUI_TYPE_ARG, current_ui_price), 4) : '--'}</Text>
          </VStack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Market Cap</Text>,
      key: 'market_cap',
      render: (item: PumpToken) => {
        return <MarketCapBlock pumpToken={item} hasProgress={true} />
      }
    },
    {
      title: <Text fontSize="14px">24H Volume (SUI)</Text>,
      key: 'vol',
      render: ({ volume_24h, TokenDetail }: { volume_24h: string; TokenDetail: PumpTokenDetail }) => {
        const result = fromDecimalsAmount(volume_24h, TokenDetail?.decimals)
        return <Text color="text_caption"> {formatNumberWithKMB(result)}</Text>
      }
    }
  ].filter(item => !item?.hidden)
}
function TokensCreatedTable({
  pageList,
  pageLoading,
  queryAddress,
  pageSize,
  isPageError
}: {
  pageList: PumpToken[]
  pageLoading: boolean
  queryAddress: string | undefined
  pageSize: number
  isPageError: boolean
}) {
  const navigate = useNavigate()
  const { getTokenAmountValue } = useTokenPrice()
  const { isApp } = useWindowWidth()
  const { jump2Swap } = useJump2Dex()

  const [currentPage, setCurrentPage] = useState(1)
  const { fetchAccountCreateTokenList } = useAccountCreateTokenList(queryAddress)
  const { maxPage } = useAccountCreateTokenListStore()

  return (
    <VStack w="100%" position="relative" gap="20px">
      <Block
        p={{
          base: '0',
          lg: '20px 0 0'
        }}
        overflow="hidden"
        border={{ base: 'transparent', lg: 'none' }}
        bg={{ base: 'transparent', lg: 'bg_secondary' }}
        borderRadius={{ base: 'none', lg: '20px' }}
      >
        {isApp ? (
          <H5MapTable<PumpToken>
            wrapStyle={{ gap: '16px' }}
            itemHeight="32px"
            dataSource={pageList}
            columns={getColumns(getTokenAmountValue, isApp)}
            loading={pageLoading}
            itemSkeletonLength={5}
            rowKey="coin_type"
            rowStyle={(_, index) => ({
              w: '100%',
              p: '16px',
              gap: '16px',
              border: '1px solid',
              borderColor: 'border',
              borderRadius: '12px',
              bg: 'bg_secondary'
            })}
            onRowClick={item => {
              Number(item?.status) >= 3 ? jump2Swap(SUI_TYPE_ARG, item?.coin_type || '') : navigate(`/trade/${item?.coin_type}`)
            }}
          />
        ) : (
          <Table
            rowKey="coin_type"
            columns={getColumns(getTokenAmountValue, isApp)}
            dataSource={pageList}
            skeletonLength={2}
            loading={pageLoading}
            rowStyle={{ h: '80px', cursor: 'pointer' }}
            onRowClick={(item: PumpToken) => {
              // navigate(`/trade/${item?.coin_type}`)
              Number(item?.status) >= 3 ? jump2Swap(SUI_TYPE_ARG, item?.coin_type || '') : navigate(`/trade/${item?.coin_type}`)
            }}
            // pagination={{
            //   total: pageLoading || isPageError ? 0 : pageSize * maxPage,
            //   size: pageSize,
            //   currentPage,
            //   onChange: current => {
            //     setCurrentPage(current)
            //     if (queryAddress) {
            //       fetchAccountCreateTokenList({
            //         account: queryAddress,
            //         page_size: pageSize,
            //         page: current
            //       })
            //     }
            //   }
            // }}
          />
        )}
        {!isPageError && !pageLoading && (
          <Center p="20px 0">
            <Pagination
              total={pageLoading || isPageError ? 0 : pageSize * maxPage}
              size={pageSize}
              currentPage={currentPage}
              onChange={current => {
                setCurrentPage(current)
                if (queryAddress) {
                  fetchAccountCreateTokenList({
                    account: queryAddress,
                    page_size: pageSize,
                    page: current
                  })
                }
              }}
            />
          </Center>
        )}
        {isPageError && !pageLoading && (
          <FetchError
            onClick={() => {
              if (queryAddress) {
                fetchAccountCreateTokenList({
                  account: queryAddress,
                  page_size: pageSize,
                  page: 1
                })
              }
            }}
          />
        )}
      </Block>
    </VStack>
  )
}

export default TokensCreatedTable
