import { PumpToken } from '@/type/pump'
import { Block } from '@cetus/design'
import { useJump2Dex } from '@cetus/hooks'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Icon, Pagination, Table } from '@cetus/ui-kit'
import H5MapTable from '@cetus/ui-kit/src/components/H5MapTable'
import { Decimal, d, formatCurrency, formatNumber } from '@cetus/utils'
import { Button, Center, HStack, Text, VStack } from '@chakra-ui/react'
import { SUI_TYPE_ARG } from '@mysten/sui/utils'
import { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import FetchError from '../common/FetchError'
import SingleHasAddress from './SingleHasAddress'
const getColumns = (getTokenAmountValue: (coinType?: string, amount?: string) => string, isApp: boolean) => {
  return [
    {
      title: <Text fontSize="14px">Name (Symbol)</Text>,
      thConfig: {
        w: '32%'
      },
      key: 'name',
      render: (item: PumpToken, index: number) => {
        return (
          <HStack
            w={{
              base: 'calc(100% - 120px)',
              lg: 'unset'
            }}
            align="center"
          >
            <SingleHasAddress
              pumpTokenInfo={item}
              w={{
                base: 'unset',
                lg: '190px'
              }}
            />
          </HStack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Contract</Text>,
      key: 'address',
      // 控制整列的显示逻辑 只在h5展示这一行
      hidden: !isApp,
      render: (item: PumpToken, index: number) => {
        return (
          <HStack
            w={{
              base: 'calc(100% - 120px)',
              lg: 'unset'
            }}
            align="center"
          >
            <SingleHasAddress
              isRowH5={true}
              pumpTokenInfo={item}
              w={{
                base: 'unset',
                lg: '190px'
              }}
            />
          </HStack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Amount</Text>,
      key: 'amount',
      render: ({ owner_balance_ui }: { owner_balance_ui: any }, index: number) => {
        return <Text color="text_caption">{formatNumber(owner_balance_ui)}</Text>
      }
    },
    {
      title: <Text fontSize="14px">Price</Text>,
      key: 'price',
      render: ({ current_ui_price }: { current_ui_price: string }) => {
        return (
          <VStack
            align={{
              base: 'flex-end',
              lg: 'flex-start'
            }}
            gap="0"
          >
            <Text color="text_caption">{formatNumber(current_ui_price, undefined, undefined, Decimal.ROUND_DOWN)} SUI</Text>
            <Text fontSize="12px"> {formatCurrency(getTokenAmountValue(SUI_TYPE_ARG, current_ui_price), 4)}</Text>
          </VStack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Value</Text>,
      key: 'value',
      render: ({ current_ui_price, owner_balance_ui }: { current_ui_price: string; owner_balance_ui: string }) => {
        const result = d(current_ui_price).mul(owner_balance_ui).toString()
        return (
          <VStack
            align={{
              base: 'flex-end',
              lg: 'flex-start'
            }}
            gap="0"
          >
            <Text color="text_caption">{formatNumber(result)} SUI</Text>
            <Text fontSize="12px"> {formatCurrency(getTokenAmountValue(SUI_TYPE_ARG, result), 4)}</Text>
          </VStack>
        )
      }
    },
    {
      title: (
        <Text
          fontSize="14px"
          display={{
            base: 'none',
            lg: 'block'
          }}
        >
          Action
        </Text>
      ),
      key: 'action',
      render: () => {
        return (
          <Button
            fontSize="14px"
            w={{
              base: '100%',
              lg: '96px'
            }}
            h={{ base: '40px', lg: '30px' }}
            mr="0"
            ml={{ base: '-8px', lg: '0' }}
            borderRadius="8px"
            variant="outline"
          >
            <Icon xlinkHref="#icon-icon_swap" svgFill="text_highlight" display={{ base: 'inline-block', lg: 'none' }} mr="4px" />
            Trade
          </Button>
        )
      }
    }
  ].filter(item => !item?.hidden)
}

function TokensHeldTable({
  pageList,
  pageLoading,
  pageSize,
  isPageError,
  queryAddress,
  onRefresh
}: {
  pageList: PumpToken[]
  pageLoading: boolean
  pageSize: number
  isPageError: boolean
  queryAddress?: string
  onRefresh: (account: string) => Promise<void>
}) {
  const navigate = useNavigate()
  const { getTokenAmountValue } = useTokenPrice()
  const [currentList, setCurrentList] = useState<PumpToken[]>([])
  const [currentPage, setCurrentPage] = useState(1)

  useEffect(() => {
    const start = d(pageSize)
      .mul(currentPage - 1)
      .toNumber()
    const end = d(pageSize).mul(currentPage).toNumber()
    setCurrentList(pageList.slice(start, end))
  }, [pageList, currentPage])

  const { jump2Swap } = useJump2Dex()

  const { isApp } = useWindowWidth()
  const maxPage = useMemo(() => {
    return Math.ceil(d(pageList?.length).div(pageSize).toNumber())
  }, [pageList])

  return (
    <VStack w="100%" position="relative" gap="20px">
      <Block
        p={{
          base: '0',
          lg: '20px 0 0'
        }}
        overflow="hidden"
        border={{ base: 'transparent', lg: 'none' }}
        bg={{ base: 'transparent', lg: 'bg_secondary' }}
        borderRadius={{ base: 'none', lg: '20px' }}
      >
        {isApp ? (
          <H5MapTable<PumpToken>
            wrapStyle={{ gap: '16px' }}
            dataSource={currentList}
            columns={getColumns(getTokenAmountValue, isApp)}
            loading={pageLoading}
            itemSkeletonLength={5}
            itemHeight="32px"
            rowKey="coin_type"
            rowStyle={(_, index) => ({
              w: '100%',
              p: '16px',
              gap: '16px',
              border: '1px solid',
              borderColor: 'border',
              borderRadius: '12px',
              bg: 'bg_secondary'
            })}
            onRowClick={item => {
              navigate(`/trade/${item?.coin_type}`)
            }}
          />
        ) : (
          <Table<PumpToken>
            rowKey="coin_type"
            columns={getColumns(getTokenAmountValue, isApp)}
            dataSource={currentList}
            loading={pageLoading}
            skeletonLength={5}
            rowStyle={{ h: '80px', cursor: 'pointer' }}
            onRowClick={(item: PumpToken) => {
              navigate(`/trade/${item?.coin_type}`)
            }}
            // pagination={{
            //   total: pageLoading || isPageError ? 0 : pageList?.length,
            //   size: pageSize,
            //   currentPage,
            //   onChange: current => {
            //     setCurrentPage(current)
            //   }
            // }}
          />
        )}
        {!isPageError && !pageLoading && (
          <Center p="20px 0">
            <Pagination
              total={pageLoading || isPageError ? 0 : pageList?.length}
              size={pageSize}
              currentPage={currentPage}
              onChange={current => {
                setCurrentPage(current)
              }}
            />
          </Center>
        )}
        {isPageError && !pageLoading && (
          <FetchError
            onClick={() => {
              if (queryAddress) {
                onRefresh(queryAddress)
              }
            }}
          />
        )}
      </Block>
    </VStack>
  )
}

export default TokensHeldTable
