import TokensCreatedTable from '@/components/profile/TokensCreatedTable'
import TokensHeldTable from '@/components/profile/TokensHeldTable'
import WalletBlock from '@/components/profile/WalletBlock'
import { useAccountCreateTokenList } from '@/hook/pump/useAccountCreateTokenList'
import { useAccountHoldTokenList } from '@/hook/pump/useAccountHoldTokenList'
import useAccountCreateTokenListStore from '@/store/accountCreateTokenList'
import useAccountHeldTokenListStore from '@/store/accountHeldTokenList'
import { SelectTab } from '@cetus/design/src/components/common'
import { useAccountStore } from '@cetus/stores'
import { NoData } from '@cetus/ui-kit'
import { VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useState } from 'react'
import { useParams } from 'react-router-dom'

export default function Profile() {
  const pageSize = 10
  const [currentTab, setCurrentTab] = useState('Tokens Held')
  const [currentTabVal, setCurrentTabVal] = useState<'Hold_coin' | 'Create_coin'>('Hold_coin')

  const tabList = [
    {
      label: 'Tokens Held',
      value: 'Hold_coin'
    },
    {
      label: 'Tokens Created',
      value: 'Create_coin'
    }
  ]
  const { address } = useParams()
  const { fetchAccountCreateTokenList, isLoadMoreError: isCreateError } = useAccountCreateTokenList(address)
  const { fetchAccountHoldTokenList, isLoadMoreError: isHoldError } = useAccountHoldTokenList(address)
  const { currentAccount } = useAccountStore()

  const queryAddress = useMemo(() => {
    return address ? address : currentAccount?.address
  }, [currentAccount?.address, address])

  const fetchList = () => {
    if (queryAddress) {
      console.log('🚀 ~ useEffect ~ address:', currentTabVal, queryAddress)
      if (currentTabVal === 'Create_coin') {
        fetchAccountCreateTokenList({
          account: queryAddress,
          page_size: pageSize,
          page: 1
        })
      } else {
        fetchAccountHoldTokenList(queryAddress)
      }
    }
  }

  useEffect(() => {
    fetchList()
  }, [queryAddress, currentTabVal])

  const { createdTokenList, createdTokenListLoading } = useAccountCreateTokenListStore()
  const { heldTokenList, heldTokenListLoading } = useAccountHeldTokenListStore()

  const pageList = useMemo(() => {
    console.log('🚀 ~ pageList ~ createdTokenList:', heldTokenList, createdTokenList)
    return !queryAddress ? [] : currentTab == 'Tokens Created' ? createdTokenList : heldTokenList
  }, [currentTab, heldTokenList, createdTokenList])

  const pageLoading = useMemo(() => {
    console.log('🚀 ~ pageList ~ heldTokenListLoading, createdTokenListLoading:', heldTokenListLoading, createdTokenListLoading)
    return currentTab == 'Tokens Created' ? createdTokenListLoading : heldTokenListLoading
  }, [currentTab, heldTokenListLoading, createdTokenListLoading])

  const isPageError = useMemo(() => {
    console.log('🚀 ~ pageList ~ sCreateError, isHoldError', isCreateError, isHoldError)
    return currentTab == 'Tokens Created' ? isCreateError : isHoldError
  }, [currentTab, isCreateError, isHoldError])

  console.log('🚀 ~ pageLoading ~ pageLoading:', pageLoading)

  return (
    <VStack align="flex-start" w="100%" position="relative" mt={{ base: '0px', lg: '52px' }}>
      <WalletBlock />
      <SelectTab
        type="borderTab"
        wrapStyle={{
          w: {
            base: '100%',
            lg: '400px'
          },
          h: '60px'
        }}
        itemStyle={{
          fontSize: '16px'
        }}
        w="50%"
        tabList={tabList}
        currentTab={currentTab}
        handleChangeTab={item => {
          setCurrentTab(item.label)
          setCurrentTabVal(item.value)
        }}
      />

      {!pageLoading && !isPageError && pageList.length == 0 ? (
        <NoData type="nodata" />
      ) : currentTab == 'Tokens Created' ? (
        <TokensCreatedTable pageList={pageList} pageLoading={pageLoading} queryAddress={queryAddress} pageSize={pageSize} isPageError={isPageError} />
      ) : (
        <TokensHeldTable
          pageList={pageList}
          pageLoading={pageLoading}
          queryAddress={queryAddress}
          onRefresh={fetchAccountHoldTokenList}
          pageSize={pageSize}
          isPageError={isPageError}
        />
      )}
    </VStack>
  )
}
