import { PumpToken } from '@/type/pump'
import { AddressCopyLink } from '@cetus/design/src/components/common'
import useExplorer from '@cetus/hooks/src/useExplorer'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { SingleCoinImage } from '@cetus/ui-kit'
import { HStack, HTMLChakraProps, VStack } from '@chakra-ui/react'
import NameSymbolBlock from '../common/NameSymbolBlock'
interface SingleHasAddressProps extends HTMLChakraProps<'div'> {
  pumpTokenInfo: PumpToken
  isRowH5?: boolean
}
export default function SingleHasAddress({ pumpTokenInfo, isRowH5 = false, ...rest }: SingleHasAddressProps) {
  const { getExplorerUrl } = useExplorer()
  const { isApp } = useWindowWidth()
  return (
    <HStack
      w="100%"
      justifyContent={{
        base: 'flex-end',
        lg: 'flex-start'
      }}
    >
      {!isRowH5 && <SingleCoinImage imageUrl={pumpTokenInfo.TokenDetail?.image} w={{ base: '24px', lg: '32px' }} h={{ base: '24px', lg: '32px' }} />}
      <VStack
        align={{
          base: 'flex-end',
          lg: 'flex-start'
        }}
        gap="0"
      >
        {!isRowH5 && <NameSymbolBlock tokenDetail={pumpTokenInfo.TokenDetail} haveTooltip={false} h="unset" p="0" w="190px" {...rest} />}(
        {(!isApp || isRowH5) && (
          <AddressCopyLink
            address={pumpTokenInfo?.coin_type}
            color={isRowH5 ? 'text_caption' : 'text_paragraph'}
            fontSize={isRowH5 ? '14px' : '12px'}
            onClickLink={() => {
              window.open(getExplorerUrl(pumpTokenInfo?.coin_type, 'coin'), '_blank')
            }}
          />
        )}
        )
      </VStack>
    </HStack>
  )
}
