import useAccountCreateTokenListStore from '@/store/accountCreateTokenList'
import { queryUserTokenListPath } from '@/type/api'
import { AccountTokenCreateQuery, PumpToken } from '@/type/pump'
import { PumpUtils } from '@/utils/pumpUtils'
import { useEffect, useState } from 'react'
import { usePumpApiDomain } from '../common/usePumpApiDomain'
import { useGetClmmPoolList } from './useGetClmmPoolList'

export function useAccountCreateTokenList(account?: string) {
  const { currAccount, createdTokenListLoading, setCreatedTokenListLoading, createdTokenList, setCreatedTokenList, setMaxPage, maxPage } =
    useAccountCreateTokenListStore()
  const { fetchClmmData } = useGetClmmPoolList()
  const [isLoadMoreError, setIsLoadMoreError] = useState<boolean>(false)
  const { fetchGetByApi } = usePumpApiDomain()

  const fetchAccountCreateTokenList = async (query: AccountTokenCreateQuery) => {
    const { page, page_size = 10, if_asc = false, order_by_type = 'marketcap', account } = query
    setCreatedTokenListLoading(true)
    setIsLoadMoreError(false)
    const params = new URLSearchParams({
      user_wallet: account,
      page: String(page),
      page_size: String(page_size),
      if_asc: String(if_asc),
      order_by_type
    })

    const api = `${queryUserTokenListPath}?${params.toString()}`
    try {
      const response = await fetchGetByApi(api)
      const list: PumpToken[] = response.tokenVolumes

      const maxPage = response.maxPage
      if (maxPage) {
        setMaxPage(Number(maxPage))
      }

      if (list) {
        console.log('🚀 ~ file: useAccountTokenList.ts:43 ~ fetchAccountTokenList ~ list:', {
          list
        })

        list.forEach((item: any) => {
          PumpUtils.formatPumpToken(item)
        })

        setCreatedTokenList(list, account)

        // 异步获取Clmm 相关信息
        fetchClmmData([...list])
      }
    } catch (error) {
      console.log('🚀 ~ file: useAccountTokenList.ts:53 ~ fetchAccountTokenList ~ error:', error)
      setIsLoadMoreError(true)
    } finally {
      setCreatedTokenListLoading(false)
    }
  }

  useEffect(() => {
    if (account === undefined || currAccount === undefined || currAccount !== account) {
      setCreatedTokenList([])
    }
  }, [account])

  return {
    createdTokenListLoading,
    createdTokenList,
    fetchAccountCreateTokenList,
    maxPage,
    isLoadMoreError
  }
}
