import { PumpToken } from '@/type/pump'
import { create, StateCreator } from 'zustand'

interface PumpTokenListState {
  //当前用户
  currAccount?: string
  // Held列表刷新Loading
  heldTokenListLoading: boolean
  setHeldTokenListLoading: (loading: boolean) => void

  // Held Token 列表
  heldTokenList: PumpToken[]
  setHeldTokenList: (list: PumpToken[], currAccount?: string) => void
}

const store: StateCreator<PumpTokenListState> = (set, get) => ({
  currAccount: undefined,
  heldTokenListLoading: false,
  heldTokenList: [],
  setHeldTokenListLoading: (loading: boolean) => {
    set(() => ({
      heldTokenListLoading: loading
    }))
  },
  setHeldTokenList: (list: PumpToken[], currAccount?: string) => {
    set(() => ({
      currAccount,
      heldTokenList: list
    }))
  }
})

const useAccountHeldTokenListStore = create(store)
export default useAccountHeldTokenListStore
